    "fonts": "node scripts/subset-font.mjs",
    "images": "node scripts/make-images.mjs",
    "build": "node scripts/subset-font.mjs && astro check && astro build && node scripts/verify-build.mjs",
    "preview": "wrangler dev --port 8820",
    "check": "astro check",
