  },
  "devDependencies": {
    "@astrojs/check": "^0.9.10",
    "@astrojs/sitemap": "^3.7.4",
    "@playwright/test": "^1.63.0",
    "astro": "^7.3.5",
    "playwright": "^1.63.0",
