/**
 * HTML 을 gzip 으로 압축해 돌려준다.
 *
 * HTML 에는 Cache-Control: no-transform 을 붙인다(public/_headers) — 빼면 Cloudflare 가 Bot Fight Mode 의
 * JavaScript 감지·분석 비콘 스크립트를 끼워 넣고 CSP 가 막아 콘솔 오류가 난다. 그런데 no-transform 이면
 * 엣지가 압축도 하지 않아 HTML 이 47KB 그대로 나간다. 그래서 여기서 직접 압축한다(엣지는 이미 압축된 본문을
 * 건드리지 않는다). JavaScript 감지는 영역 전체 설정이라 끄지 않는다 — 이룸뷰티(cosmetics)가 쓰고 있다.
 */
async function serveHtml(req: Request, env: Env): Promise<Response> {
  // 압축본에는 약한 ETag 를 붙여 보내므로, 되돌아온 If-None-Match 의 W/ 를 떼어 자산 쪽 304 비교가 맞게 한다
  let assetReq = req;
  const inm = req.headers.get('if-none-match');
  if (inm?.startsWith('W/')) {
    const h = new Headers(req.headers);
    h.set('if-none-match', inm.slice(2));
    assetReq = new Request(req, { headers: h });
  }
  const res = await env.ASSETS.fetch(assetReq);
  const type = res.headers.get('content-type') ?? '';
  const accepts = /\bgzip\b/i.test(req.headers.get('accept-encoding') ?? '');
  if (req.method !== 'GET' || !res.body || !type.startsWith('text/html') || !accepts || res.headers.has('content-encoding')) {
    return res;
  }
  const headers = new Headers(res.headers);
  headers.set('content-encoding', 'gzip');
  headers.delete('content-length');
  headers.append('vary', 'Accept-Encoding');
  const etag = headers.get('etag');
  if (etag && !etag.startsWith('W/')) headers.set('etag', `W/${etag}`);
  // encodeBody: 'manual' — 본문이 이미 압축되었음을 런타임에 알린다(다시 압축하지 않음)
  const init = { status: res.status, statusText: res.statusText, headers, encodeBody: 'manual' } as ResponseInit;
  return new Response(res.body.pipeThrough(new CompressionStream('gzip')), init);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (url.pathname === '/api/inquiry') return handleInquiry(req, env);
    if (url.pathname === '/api/resend-inbound') return handleInbound(req, env);
    if (url.pathname.startsWith('/api/')) return fail(404, 'not_found');
