/** 이 길이를 넘는 mailto 주소는 일부 메일 앱(특히 Windows)에서 잘리거나 열리지 않는다 */
const MAILTO_SAFE_LENGTH = 1800;
const FIELD_ORDER = ['type', 'name', 'email', 'company', 'message', 'consent'] as const;

interface TurnstileApi {
  render(el: HTMLElement, opts: Record<string, unknown>): string;
  execute(id: string): void;
  reset(id: string): void;
}

declare global {
  interface Window {
    turnstile?: TurnstileApi;
    irumxTurnstileReady?: () => void;
  }
}

let turnstileLoading: Promise<TurnstileApi> | null = null;

/** Turnstile 스크립트는 문의 페이지(보내기 방식)에서만 불러온다 */
function loadTurnstile(): Promise<TurnstileApi> {
  if (window.turnstile) return Promise.resolve(window.turnstile);
  if (turnstileLoading) return turnstileLoading;
  turnstileLoading = new Promise<TurnstileApi>((resolve, reject) => {
    const timer = window.setTimeout(() => reject(new Error('turnstile timeout')), 20000);
    window.irumxTurnstileReady = () => {
      window.clearTimeout(timer);
      if (window.turnstile) resolve(window.turnstile);
      else reject(new Error('turnstile missing'));
    };
    const s = document.createElement('script');
    s.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit&onload=irumxTurnstileReady';
    s.async = true;
    s.onerror = () => {
      window.clearTimeout(timer);
      reject(new Error('turnstile load failed'));
    };
    document.head.append(s);
  });
  turnstileLoading.catch(() => {
    turnstileLoading = null;
  });
  return turnstileLoading;
}

function uuid(): string {
  if (crypto.randomUUID) return crypto.randomUUID();
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

